-- 11·14 攻击事件 · 写入「铭记历史」（#/history）
-- 正文 = 调查报告（附卷八卷）+ 后续两次事件 + 防护边界与开关实测。UNHEX 传，避免转义损坏。
-- 幂等：不存在则插入；已存在则整份替换。
-- 生成时间：2026-11-21（托管规则集上线）

SET NAMES utf8mb4;
SET @doc := CONVERT(UNHEX('') USING utf8mb4);

INSERT INTO `incidents`
  (`oid`, `title`, `started_at`, `ended_at`, `summary`, `doc`, `culprit`, `severity`, `is_public`, `created_at`, `updated_at`)
SELECT '20261116003471', '11·14 攻击事件', '2026-11-14 09:00:00', '2026-11-15 09:52:00',
       '第一次注水与打配额，第二次迁站期间继续灌流量，第三次在 11-18/19 与 11-21 两次试探；两个试探机房的全部网段已封，ASN 名单 69 家，托管规则集 42 条上线。', @doc,
       '未确认 · 与 11·3 无关联，不作指认', 'severe', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `incidents` WHERE `title` = '11·14 攻击事件');

UPDATE `incidents` SET `doc` = @doc, `summary` = '第一次注水与打配额，第二次迁站期间继续灌流量，第三次在 11-18/19 与 11-21 两次试探；两个试探机房的全部网段已封，ASN 名单 69 家，托管规则集 42 条上线。', `updated_at` = UTC_TIMESTAMP()
 WHERE `title` = '11·14 攻击事件';
